/**
 * Medical Incident Service.
 */
import type {
  MedicalIncident,
  MedicalIncidentFilters,
  MedicalIncidentStats,
  MedicalIncidentReport,
  MedicalIncidentReportFilters,
  StaffAnalysis,
  ManagementAnalysis,
  IncidentStatus,
} from '../../models/MedicalIncident';
import type { PagedResult } from './endpoint';
import { medicalIncidentEndpoint } from './endpoint';

export const medicalIncidentService = {
  getList: (
    filters: MedicalIncidentFilters,
    page = 1,
    pageSize = 20,
  ): Promise<PagedResult<MedicalIncident>> =>
    medicalIncidentEndpoint.getList(filters, page, pageSize),

  getStats: (filters?: { isServiceMismatch?: boolean; hasFall?: boolean; reportingDepartmentId?: string; dateFrom?: string; dateTo?: string }): Promise<MedicalIncidentStats> =>
    medicalIncidentEndpoint.getStats(filters),

  getById: (id: string): Promise<MedicalIncident | null> =>
    medicalIncidentEndpoint.getById(id),

  create: (data: Partial<MedicalIncident>): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.create(data),

  update: (id: string, data: Partial<MedicalIncident>): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.update(id, data),

  delete: (id: string): Promise<void> =>
    medicalIncidentEndpoint.delete(id),

  startAnalysis: (id: string): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.startAnalysis(id),

  submitAnalysis: (id: string): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.submitAnalysis(id),

  submitFeedback: (id: string, rating: number, feedback: string): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.submitFeedback(id, rating, feedback),

  toggleServiceMismatch: (id: string, isServiceMismatch: boolean): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.toggleServiceMismatch(id, isServiceMismatch),

  toggleNotMedicalIncident: (id: string, isNotMedicalIncident: boolean): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.toggleNotMedicalIncident(id, isNotMedicalIncident),

  saveAnalysis: (
    id: string,
    staffAnalysis: StaffAnalysis | null,
    managementAnalysis: ManagementAnalysis | null,
  ): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.saveAnalysis(id, staffAnalysis, managementAnalysis),

  saveStaffAnalysis: (
    id: string,
    staffAnalysis: StaffAnalysis,
  ): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.saveStaffAnalysis(id, staffAnalysis),

  saveManagementAnalysis: (
    id: string,
    managementAnalysis: ManagementAnalysis,
  ): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.saveManagementAnalysis(id, managementAnalysis),

  getReport: (filters: MedicalIncidentReportFilters): Promise<MedicalIncidentReport> =>
    medicalIncidentEndpoint.getReport(filters),

  /** Export all records matching current filters → returns .xlsx Blob for download. */
  exportAll: (filters: MedicalIncidentFilters): Promise<Blob> =>
    medicalIncidentEndpoint.exportAll(filters),

  /** Check which legacyIds (MSSC) already exist — used by import wizard to skip duplicates. */
  checkLegacyIds: (legacyIds: string[]): Promise<string[]> =>
    medicalIncidentEndpoint.checkLegacyIds(legacyIds),

  /** All IDs matching list filters — for select-all across pages. */
  getAllIds: (filters: MedicalIncidentFilters): Promise<string[]> =>
    medicalIncidentEndpoint.getAllIds(filters),

  /** Update the status of multiple incidents in one request. */
  batchUpdateStatus: (ids: string[], status: IncidentStatus): Promise<MedicalIncident[]> =>
    medicalIncidentEndpoint.batchUpdateStatus(ids, status),

  /** Batch status update in chunks of 200 (BFF limit). */
  batchUpdateStatusInChunks: async (ids: string[], status: IncidentStatus): Promise<MedicalIncident[]> => {
    const CHUNK = 200;
    const updated: MedicalIncident[] = [];
    for (let i = 0; i < ids.length; i += CHUNK) {
      const chunk = ids.slice(i, i + CHUNK);
      const result = await medicalIncidentEndpoint.batchUpdateStatus(chunk, status);
      updated.push(...result);
    }
    return updated;
  },
};
